    internal InnerOrganizationCentralizationRuleCentralizationRuleSourceFactory SourceFactory { get; set; }

    protected override Humidifier.ObservabilityAdmin.OrganizationCentralizationRuleTypes.CentralizationRule Create()
    {
        var centralizationRuleResult = CreateCentralizationRule();
        factoryAction?.Invoke(centralizationRuleResult);

        return centralizationRuleResult;
    }

    private Humidifier.ObservabilityAdmin.OrganizationCentralizationRuleTypes.CentralizationRule CreateCentralizationRule()
    {
        var centralizationRuleResult = new Humidifier.ObservabilityAdmin.OrganizationCentralizationRuleTypes.CentralizationRule();

        return centralizationRuleResult;
    }
    public override void CreateChildren(Humidifier.ObservabilityAdmin.OrganizationCentralizationRuleTypes.CentralizationRule result)
    {
        base.CreateChildren(result);

        result.Destination ??= DestinationFactory?.Build();
        result.Source ??= SourceFactory?.Build();
    }

} // End Of Class

